					reflection.a *= ssrMask;
					}

					if (reflection.a < 1.0){
						vec3 skyRefPos    =reflect(nViewPos, normal);

						#if defined (OVERWORLD)

							skyReflection=GetSkyColor(skyRefPos, true);

							#ifdef REFLECTION_ROUGH
								cloudMixRate = smoothness * smoothness * (3.0 - 2.0 * smoothness);
							#endif

