								if (moonVisibility > 0.0){
									skyReflection+=DrawAurora(skyRefPos * 100.0, dither, 15) * (AURORA_REFLECTION_STRENGTH * 2.0) * cloudMixRate;
								}
								#endif
							#endif

							#ifdef METAL_CLOUDS_REFLECTION
								#if REALISTIC_CLOUDS == 1
