							#endif

							float NoU            =clampInv11(dot(normal, upVec));
							float NoE            =clampInv11(dot(normal, eastVec));
							float vanillaDiffuse =(0.25 * NoU + 0.75) + (0.5 - abs(NoE)) * (1.0 - abs(NoU)) * 0.1;
